+func configureAgentColor(name types.AgentName) string {
+	switch name {
+	case agent.AgentNameClaudeCode:
+		return "#e8864a"
+	case agent.AgentNameCodex:
+		return "#34a37f"
+	case agent.AgentNameCopilotCLI:
+		return "#d162c4"
+	case agent.AgentNameGemini:
+		return "#5b93e8"
+	case agent.AgentNameOpenCode:
